(function(){'use strict';
const C=window.CAGE_ADMISSIONS_COMMON,esc=C.esc,$=id=>document.getElementById(id),api=()=>window.CAGE_BACKEND;let data=null,working=null,category='RPL',status='',query='',loading=false;
try{const saved=sessionStorage.getItem('cage-admissions-programme');if(C.categories.includes(saved))category=saved;}catch{}
const allowed=()=>api()?.moduleLevel('training')==='edit'&&['admin','manager'].includes(api()?.currentProfile()?.role);
const active=()=>document.querySelector('[data-academy="tab"][data-id="applications"][aria-selected="true"]');
const button=(action,label,id='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}-button" data-ad="${action}" data-id="${esc(id)}">${label}</button>`;
const field=(key,label,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${key}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;
const area=(key,label,value='')=>`<label class="field field-wide"><span>${label}</span><textarea name="${key}">${esc(value)}</textarea></label>`;
const select=(key,label,options,value)=>`<label class="field"><span>${label}</span><select name="${key}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
function modal(title,body){let d=$('admission-dialog');if(!d){d=document.createElement('dialog');d.id='admission-dialog';d.className='app-dialog academy-dialog ad-admin-dialog';document.body.append(d);}d.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2>${button('close','×')}</div>${body}<p class="form-error" role="alert" id="ad-admin-error"></p>`;if(!d.open)d.showModal();return d;}
function load(){if(loading)return loading;if(!allowed())return Promise.resolve();loading=(async()=>{try{data=await api().admissionData();render();}catch(e){if(active())$('academy-content').innerHTML=`<p class="academy-error">${esc(e.message)}</p>${button('refresh','Retry')}`;}finally{loading=false;}})();return loading;}
function render(target){const root=target||$('academy-content');if(!root||(!target&&!active()))return;if(!allowed()){root.innerHTML='<div class="academy-empty">Applications and identity documents are restricted to administrators and managers with Training edit access.</div>';return;}if(!data){root.innerHTML='<p>Loading applications…</p>';load();return;}
 const applications=data.applications.filter(a=>a.category===category&&(!status||a.status===status)&&`${a.full_name} ${a.email} ${a.phone}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.submitted_at.localeCompare(a.submitted_at));
 const pending=data.files.filter(f=>f.kind==='payment'&&f.review_status==='Pending'&&applications.some(a=>a.id===f.application_id)).length;
 root.innerHTML=`<div class="ad-programmes" role="group" aria-label="Application programme">${C.categories.map(c=>`<button type="button" data-ad="programme" data-id="${esc(c)}" aria-pressed="${category===c}" class="ad-programme ${category===c?'active':''}"><strong>${esc(c)}</strong><span>${data.applications.filter(a=>a.category===c).length} applications · ${data.intakes.filter(i=>i.category===c).length} calls</span></button>`).join('')}</div><div class="ad-admin-toolbar"><div><h2>${esc(category)} applications & calls</h2><p>Publish the next intake, review applicants and verify payment evidence.</p></div><div>${button('new','New '+esc(category)+' call','',true)}${button('refresh','Refresh')}<a class="secondary-button" href="./apply.html" target="_blank" rel="noopener">Open application portal ↗</a></div></div><div class="academy-metrics academy-stats"><article class="academy-stat"><strong>${applications.length}</strong><span>Applications</span></article><article class="academy-stat"><strong>${applications.filter(a=>a.status==='New').length}</strong><span>New</span></article><article class="academy-stat"><strong>${pending}</strong><span>Proofs awaiting review</span></article><article class="academy-stat"><strong>${applications.filter(a=>a.status==='Accepted'||a.status==='Enrolled').length}</strong><span>Accepted / enrolled</span></article></div><div class="ad-admin-filters"><select id="ad-status" aria-label="Filter application status"><option value="">All statuses</option>${['New','Under review','Accepted','Waitlisted','Declined','Enrolled'].map(c=>`<option ${status===c?'selected':''}>${c}</option>`).join('')}</select><input id="ad-search" type="search" placeholder="Search name, email or phone" value="${esc(query)}"></div><details class="ad-call-panel" open><summary>Application calls and editable forms</summary><div class="academy-cards">${data.intakes.filter(c=>c.category===category).map(c=>`<article class="academy-card"><span class="academy-tag">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${c.published?(c.accepting?'Published · accepting applications':'Published · closed'):'Draft · private'} · ${c.start_date?esc(c.start_date):'Dates not set'}</p><footer>${button('edit','Edit fields & schedule',c.id)}${button('duplicate','Duplicate for next call',c.id)}${c.published?`<a href="./apply.html?call=${c.id}" target="_blank" rel="noopener">Public call ↗</a>`:''}</footer></article>`).join('')||'<p class="academy-empty">No calls for this programme yet. Create a call to get started.</p>'}</div></details><div class="academy-table"><table><thead><tr><th>Applicant</th><th>Course / call</th><th>Status</th><th>Payment evidence</th><th></th></tr></thead><tbody>${applications.map(a=>{const proofs=data.files.filter(f=>f.application_id===a.id&&f.kind==='payment');return `<tr><td><strong>${esc(a.full_name)}</strong><small>${esc(a.email)} · ${esc(a.phone)}</small></td><td>${esc(a.category)}<small>${esc(a.form_snapshot.title)}</small></td><td>${esc(a.status)}</td><td>${proofs.length?proofs.map(f=>esc(f.review_status)).join(', '):'Not uploaded'}</td><td>${button('review','Review',a.id)}</td></tr>`;}).join('')||'<tr><td colspan="5">No applications match these filters.</td></tr>'}</tbody></table></div><p class="academy-muted">Verified evidence does not create a Finance payment. Record and reconcile the payment in Finance separately.</p>`;
}
function makeNew(){return {id:'',revision:0,category:category,title:'',description:'',published:false,accepting:false,start_date:'',closes_on:'',fee:0,currency:'MWK',venue:'',payment_instructions:'',fields:C.fields(category),schedule:[],schedule_notes:'Schedule subject to change, including weather-dependent flights. Participants arrange transport to training venues. Any exam-retake costs are borne by participants.'};}
function editor(id,duplicate=false){working=id?structuredClone(data.intakes.find(c=>c.id===id)):makeNew();if(duplicate){working.id='';working.title+=' — next call';working.published=false;working.accepting=false;working.start_date='';working.closes_on='';working.schedule=working.schedule.map(r=>({...r,date:''}));}drawEditor();}
function readEditor(){const f=$('ad-intake-form');if(!f)return working;const values=new FormData(f);for(const key of ['title','description','venue','payment_instructions','schedule_notes','currency'])working[key]=String(values.get(key)||'');working.category=f.elements.category.value;working.fee=Number(values.get('fee'));working.start_date=values.get('start_date')||null;working.closes_on=values.get('closes_on')||null;working.published=f.elements.published.checked;working.accepting=f.elements.accepting.checked;
 working.fields=[...f.querySelectorAll('[data-field-row]')].map(row=>({id:row.dataset.fieldRow,label:row.querySelector('[data-field-label]').value,type:row.querySelector('[data-field-type]').value,required:row.querySelector('[data-field-required]').checked,options:row.querySelector('[data-field-options]').value.split('\n').map(s=>s.trim()).filter(Boolean)}));
 working.schedule=[...f.querySelectorAll('[data-schedule-row]')].map((row,i)=>({offset:Number(row.dataset.offset),date:row.querySelector('[data-day-date]').value,phase:row.querySelector('[data-day-phase]').value,slots:[...row.querySelectorAll('[data-day-slot]')].map(slot=>({time:slot.querySelector('[data-slot-time]').value,topic:slot.querySelector('[data-slot-topic]').value}))}));f.dataset.draft=JSON.stringify(working);return working;}
function drawEditor(){const c=working,core=C.core(c.category);modal(c.id?'Edit application call':'New application call',`<form id="ad-intake-form" data-record="${esc(c.id)}"><div class="form-grid">${select('category','Course',C.categories,c.category)}${field('title','Call title',c.title,'text','required maxlength="160"')}${field('start_date','First training date',c.start_date,'date')}${field('closes_on','Applications close on',c.closes_on,'date')}${field('fee','Course fee',c.fee,'number','required min="0" step="0.01"')}${field('currency','Currency',c.currency,'text','required pattern="[A-Z]{3}" maxlength="3"')}${field('venue','Venue / delivery format',c.venue)}${area('description','Public call description',c.description)}${area('payment_instructions','Payment instructions shown to applicants after application',c.payment_instructions)}</div><h3>Editable application fields</h3><p class="academy-muted">Edit labels, add questions and choices, reorder or remove optional fields. Core contact and guardian fields remain required. Saved applications retain their original questions.</p><div id="ad-field-rows">${c.fields.map((f,i)=>`<article class="ad-field-editor" data-field-row="${esc(f.id)}"><input data-field-label value="${esc(f.label)}" aria-label="Field label" required maxlength="200"><select data-field-type aria-label="Field type" ${core.includes(f.id)?'disabled':''}>${['text','textarea','email','tel','date','number','select','checkbox'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select><label class="ad-check"><input type="checkbox" data-field-required ${f.required?'checked':''} ${core.includes(f.id)?'disabled':''}>Required</label><textarea data-field-options aria-label="Choices, one per line" placeholder="For select fields: one choice per line">${esc((f.options||[]).join('\n'))}</textarea><div>${i?button('field-up','↑',String(i)):''}${!core.includes(f.id)?button('field-remove','Remove',String(i)):''}</div></article>`).join('')}</div>${button('field-add','＋ Add field')}<p class="academy-muted">National ID / passport / license upload is ${c.category==='STEM'?'optional':'required'} for this course. Payment-proof uploads are provided after application.</p><h3>Next timetable</h3><p class="academy-muted">For RPL and RPL Refresher, set the next call's dates before publishing. The supplied full-course example can be adapted for a refresher. All times are Malawi time.</p><div class="ad-inline-actions">${button('schedule-example','Load example RPL schedule')}${button('schedule-shift','Set dates from first training date')}${button('day-add','＋ Add schedule day')}</div><div id="ad-schedule-rows">${c.schedule.map((r,i)=>`<article class="ad-schedule-editor" data-schedule-row="${i}" data-offset="${r.offset??i}"><div class="ad-day-heading"><input type="date" data-day-date value="${esc(r.date)}" aria-label="Day date"><input data-day-phase value="${esc(r.phase)}" placeholder="Week / phase / location" aria-label="Training phase">${button('day-remove','Remove day',String(i))}</div>${r.slots.map(slot=>`<div data-day-slot><input data-slot-time value="${esc(slot.time)}" placeholder="Time / TBD" aria-label="Session time"><input data-slot-topic value="${esc(slot.topic)}" placeholder="Session topic" aria-label="Session topic"></div>`).join('')}</article>`).join('')}</div>${area('schedule_notes','Schedule notes',c.schedule_notes)}<div class="ad-publish"><label class="ad-check"><input type="checkbox" name="published" ${c.published?'checked':''}>Publish this call and timetable</label><label class="ad-check"><input type="checkbox" name="accepting" ${c.accepting?'checked':''}>Accept applications</label></div><div class="dialog-actions"><button class="primary-button" type="submit">Save call</button>${button('preview','Preview timetable')}</div></form>`);$('ad-intake-form').elements.category.disabled=Boolean(c.id);$('ad-intake-form').dataset.draft=JSON.stringify(c);}
function review(id){const a=data.applications.find(r=>r.id===id);if(!a)throw new Error('Application no longer available');const files=data.files.filter(f=>f.application_id===id).sort((a,b)=>a.created_at.localeCompare(b.created_at));modal('Review application',`<div class="ad-review-heading"><span class="academy-tag">${esc(a.category)} · ${esc(a.status)}</span><h3>${esc(a.full_name)}</h3><p>${esc(a.email)} · ${esc(a.phone)}</p><p>${esc(a.form_snapshot.title)}</p></div><details open><summary>Submitted answers</summary>${a.form_snapshot.fields.map(f=>`<div class="stem-answer"><strong>${esc(f.label)}</strong><p>${esc(typeof a.answers[f.id]==='boolean'?(a.answers[f.id]?'Yes':'No'):a.answers[f.id]||'—')}</p></div>`).join('')}</details><h3>Private identity document</h3><p>${esc(a.identity_type||'Not provided (optional for STEM)')}</p>${files.filter(f=>f.kind==='identity').map(f=>button('file','Open '+esc(f.file_name),f.id)).join('')}<h3>Payment proof</h3>${files.filter(f=>f.kind==='payment').map(f=>`<article class="ad-proof-review"><strong>${esc(a.form_snapshot.currency)} ${Number(f.amount).toLocaleString()} · ${esc(f.payment_date)}</strong><p>${esc(f.payment_reference)}</p>${button('file','Open proof',f.id)}<form class="ad-proof-form" data-record="${f.id}">${select('status','Review', ['Pending','Verified','Rejected'],f.review_status).replace('<select ',`<select id="proof-status-${f.id}" `)}${area('note','Note visible to applicant',f.review_note).replace('<textarea ',`<textarea id="proof-note-${f.id}" `)}<button class="secondary-button">Save proof review</button></form></article>`).join('')||'<p class="academy-muted">No payment proof received yet.</p>'}<form id="ad-review-form" data-record="${a.id}">${a.learner_id?`<p>This application is linked to an enrolled learner.</p><div class="dialog-actions">${button('enrol-email','Send / retry congratulatory email',a.id)}</div>`:select('status','Application status',['New','Under review','Accepted','Waitlisted','Declined'],a.status).replace('<select ',`<select id="application-status-${a.id}" `)}${area('note','Internal staff notes',a.staff_notes).replace('<textarea ',`<textarea id="application-note-${a.id}" `)}<div class="dialog-actions">${!a.learner_id?'<button class="primary-button">Save application review</button>':''}${!a.learner_id?button('enrol','Enrol in cohort',a.id):''}</div></form><p class="academy-muted">Verify the payment independently. Proof review does not add a payment to Finance.</p>`);}
async function enrol(id){const a=data.applications.find(r=>r.id===id),training=await api().loadTraining();const cohorts=training.cohorts.filter(c=>!['Completed','Cancelled'].includes(c.status)&&training.courses.some(t=>t.id===c.course_id&&(t.category===a.category||(a.category==='Industry Specific'&&['Technical','Corporate','Other'].includes(t.category)))));if(!cohorts.length)throw new Error('Create an active cohort for this course first');modal('Enrol applicant',`<form id="ad-enrol-form" data-record="${id}"><p>Confirm the learner details. The application must be accepted and any required fee must have verified payment evidence.</p><div class="form-grid"><label class="field"><span>Cohort</span><select name="cohort">${cohorts.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${field('full_name','Learner name',a.full_name,'text','required')}${field('date_of_birth','Date of birth',a.answers.date_of_birth,'date')}${field('email','Contact email',a.email,'email','required')}${field('phone','Contact phone',a.phone,'text','required')}${field('guardian_name','Guardian name',a.answers.guardian_name)}${field('guardian_phone','Guardian phone',a.answers.guardian_phone)}<label class="ad-check"><input name="guardian_consent" type="checkbox" ${a.answers.guardian_consent===true?'checked':''}>Guardian consent checked</label></div><button class="primary-button">Create learner record</button></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ad]');if(!b)return;const action=b.dataset.ad,id=b.dataset.id;try{
 if(action==='programme'&&C.categories.includes(id)){category=id;status='';query='';try{sessionStorage.setItem('cage-admissions-programme',category);}catch{}render();return;}
 if(action==='preview-close')$('ad-schedule-preview').close();if(action==='refresh')await load();if(action==='close')$('admission-dialog').close();if(action==='new')editor();if(action==='edit'||action==='duplicate')editor(id,action==='duplicate');if(action==='review')review(id);if(action==='enrol')await enrol(id);if(action==='enrol-email'){b.disabled=true;try{await api().admissionEnrolmentEmail(id);showToast('Congratulatory email sent.');}finally{b.disabled=false;}}if(action==='file'){b.disabled=true;try{const url=await api().admissionFile(id);const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();}finally{b.disabled=false;}}
 if(['field-add','field-up','field-remove','day-add','day-remove','schedule-example','schedule-shift','preview'].includes(action)){
 readEditor();const i=Number(id);if(action==='field-add')working.fields.push({id:'q_'+crypto.randomUUID().slice(0,8),label:'New question',type:'text',required:false,options:[]});if(action==='field-up')[working.fields[i-1],working.fields[i]]=[working.fields[i],working.fields[i-1]];if(action==='field-remove')working.fields.splice(i,1);if(action==='day-remove')working.schedule.splice(i,1);if(action==='day-add')working.schedule.push({offset:working.schedule.length,date:'',phase:'Training',slots:Array.from({length:3},()=>({time:'',topic:''}))});if(action==='schedule-example')working.schedule=C.exampleSchedule();if(action==='schedule-shift')working.schedule=C.shiftSchedule(working.schedule,working.start_date);
 if(action==='preview'){let d=$('ad-schedule-preview');if(!d){d=document.createElement('dialog');d.id='ad-schedule-preview';d.className='app-dialog ad-admin-dialog';document.body.append(d);}d.innerHTML=`<button type="button" data-ad="preview-close">Close preview</button>${C.scheduleHTML(working)}`;d.showModal();}else drawEditor();}
 }catch(err){const p=$('ad-admin-error');if(p)p.textContent=err.message;else showToast(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='ad-status'){status=e.target.value;render();}if(e.target.closest('#ad-intake-form')&&e.target.name==='category'){readEditor();working.fields=C.fields(working.category);drawEditor();}else if(e.target.closest('#ad-intake-form'))readEditor();});
document.addEventListener('input',e=>{if(e.target.id==='ad-search'){query=e.target.value;const pos=e.target.selectionStart;render();$('ad-search').focus();$('ad-search').setSelectionRange(pos,pos);}if(e.target.closest('#ad-intake-form'))readEditor();});
document.addEventListener('submit',async e=>{const f=e.target;if(!['ad-intake-form','ad-review-form','ad-enrol-form'].includes(f.id)&&!f.matches('.ad-proof-form'))return;e.preventDefault();if(f.dataset.submitting)return;f.dataset.submitting='true';const b=e.submitter;b.disabled=true;try{const v=Object.fromEntries(new FormData(f));if(f.id==='ad-intake-form'){const c=C.validate(readEditor());await api().admissionSave(c,c.id,c.revision);$('admission-dialog').close();}else if(f.id==='ad-review-form'){await api().admissionReview(f.dataset.record,v.status,v.note);$('admission-dialog').close();}else if(f.id==='ad-enrol-form'){v.guardian_consent=!!v.guardian_consent;const result=await api().admissionEnrol(f.dataset.record,v.cohort,v);$('admission-dialog').close();await window.CAGE_ACADEMY?.load();if(result?.emailWarning)showToast('Learner enrolled. '+result.emailWarning+' Use the application record to retry the email.');else showToast('Learner enrolled and congratulatory email sent.');}else await api().admissionPayment(f.dataset.record,v.status,v.note);await load();if(f.id!=='ad-enrol-form')showToast('Academy application changes saved.');}catch(err){$('ad-admin-error').textContent=err.message;}finally{delete f.dataset.submitting;b.disabled=false;}});
window.addEventListener('cage:session-ready',()=>{data=null;working=null;status='';query='';});
window.CAGE_ADMISSIONS={render,async restore(saved){if(!allowed())return;await load();const f=saved.forms.find(f=>['ad-intake-form','ad-review-form','ad-enrol-form'].includes(f.id));if(f?.id==='ad-intake-form'){working=JSON.parse(f.data.draft);drawEditor();}else if(f?.id==='ad-review-form')review(f.data.record);else if(f?.id==='ad-enrol-form')await enrol(f.data.record);}};
})();
